ExternalServiceRegistration.schema:
{
  "openapi": "3.0.0",
  "info": {
    "title": "Precision Pulley & Idler Open API",
    "description": "This is a general Open API to expose data and endpoints to execute business logic.\n\nRequest an API key from: TBD<TBD>",
    "contact": {
      "email": "wteeter@ppi-global.com"
    },
    "version": "1.3.0"
  },
  "servers": [{
      "url": "https://dev-precision-open-api.azurewebsites.net/"
    },
    {
      "url": "https://prod-precision-open-api.azurewebsites.net/"
    }
  ],
  "security": [{
    "api_auth": []
  }],
  "paths": {
    "/order": {
      "put": {
        "tags": [
          "Order"
        ],
        "summary": "Create an order",
        "description": "This creates an order in the PPI system. If any exception to order processing is encountered after being ingested, a PPI representative will contact the order requester via the input payload's `contactName`\n\nRegarding purchase orders, `purchaseOrder.number` is always required. `purchaseOrder.url` will be used if available, otherwise submit `purchaseOrder.documentType` and `purchaseOrder.document`, the latter of which is a base64 encoded document. If all three are submitted, `purchaseOrder.url` will be used and the other two parameters are ignored.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Order"
              }
            }
          }
        },
        "responses": {
          "202": {
            "description": "Order was successfully received",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "message": {
                      "type": "string"
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          }
        }
      }
    },
    "/order/salesforce/{externalID}/invoice": {
      "get": {
        "tags": [
          "Order"
        ],
        "summary": "Retrieve an invoice document",
        "description": "This returns a base64 encoded PDF document. \n\nSame result and logic as /order/{orderNumber}/{orderDate}/invoice. Modified to handle SalesForce's external ID as one path parameter",
        "parameters": [{
          "in": "path",
          "name": "externalID",
          "required": true,
          "schema": {
            "type": "string",
            "description": "Should be in the format '<orderNumber><orderDate>' where orderNumber is zero padded to six digits"
          }
        }],
        "responses": {
           "200": {
            "description": "Invoice found and returned",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "invoicePDF": {
                      "type": "string",
                      "format": "base64"
                    }
                  }
                }
              }
            }
          },          
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          },
          "404": {
            "description": "Invoice not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          }
        }
      }
    },
    "/order/{orderNumber}/{orderDate}/invoice": {
      "get": {
        "tags": [
          "Order"
        ],
        "summary": "Retrieve an invoice document",
        "description": "This returns a base64 encoded PDF document",
        "parameters": [{
            "in": "path",
            "name": "orderNumber",
            "required": true,
            "schema": {
              "$ref": "#/components/schemas/OrderNumber"
            }
          },
          {
            "in": "path",
            "name": "orderDate",
            "required": true,
            "schema": {
              "type": "string",
              "format": "date"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Invoice found and returned",
            "content": {
              "application/pdf": {
                "schema": {
                  "type": "string",
                  "format": "binary"
                }
              }
            }
          },
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          },
          "404": {
            "description": "Invoice not found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          }
        }
      }
    },
    "/item/{itemNumber}/inventory": {
      "get": {
        "tags": [
          "Item"
        ],
        "summary": "Retrieves inventory information for one item",
        "description": "Do **_not_** use this endpoint to determine if a collection of items with a non-null `quantityAvailableToAssemble` can come out of one warehouse. Use `/availableToAssemble` for this purpose. An explanation can be found in the description of that endpoint.\n\nThis will return an array of objects where each object holds the availability of the item as well as the warehouse where that availability exists.\n\n`quantityAvailable` will be `null` iff `quantityAvailableToAssemble` is not `null`, and `quantityAvailableToAssemble` will be `null` iff `quantityAvailable` is not `null`. This is true across all warehouses for any particular item.",
        "parameters": [{
          "in": "path",
          "name": "itemNumber",
          "required": true,
          "schema": {
            "$ref": "#/components/schemas/ItemNumber"
          }
        }],
        "responses": {
          "200": {
            "description": "successful operation",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "type": "object",
                    "properties": {
                      "warehouse": {
                        "$ref": "#/components/schemas/Warehouse"
                      },
                      "quantityAvailable": {
                        "type": "integer"
                      },
                      "quantityAvailableToAssemble": {
                        "type": "integer"
                      }
                    }
                  }
                },
                "example": [{
                    "quantityAvailable": 0,
                    "quantityAvailableToAssemble": null,
                    "warehouse": {
                      "id": "1",
                      "name": "Pella",
                      "address": {
                        "contact": null,
                        "street1": "300 S.E. 14TH STREET",
                        "street2": "P.O. BOX 287",
                        "city": "PELLA",
                        "state": "IA",
                        "zip": 50219
                      }
                    }
                  },
                  {
                    "quantityAvailable": 0,
                    "quantityAvailableToAssemble": null,
                    "warehouse": {
                      "id": "U",
                      "name": "Midwest Service Center",
                      "address": {
                        "contact": null,
                        "street1": "2254 AVENUE OF INDUSTRY",
                        "street2": "",
                        "city": "CORNING",
                        "state": "IA",
                        "zip": 50841
                      }
                    }
                  }
                ]
              }
            }
          },
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          }
        }
      }
    },
    "/availableToAssemble": {
      "post": {
        "tags": [
          "Item"
        ],
        "summary": "Determines if the items passed can be fulfilled with one order",
        "description": "This is a `POST` route due to the potential amount of data required to be sent with this endpoint. No creation or modification of data happens with this route. It is effectively a `GET` with a payload.\n\nSome PPI product is stocked as components which are assembled upon order. There can be cases where two different PPI products share the same sub-component so the independent `/item/{itemNumber}/inventory` check isn't sufficient for more than one assembled item. \n\nThis endpoint takes in a list of PPI products and determines if a PPI warehouse can fulfill all products from at least one warehouse. If PPI can fulfill all products, the warehouses that are eligible for fulfillment are also returned here.\n\nIf a non-assembled component is passed here, the endpoint will check the individual's availability (not availability to assemble) which is the same as the value from `/item/{itemNumber}/inventory`. ",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "shippingAddress": {
                    "$ref": "#/components/schemas/Address"
                  },
                  "items": {
                    "type": "array",
                    "items": {
                      "type": "object",
                      "properties": {
                        "itemNumber": {
                          "$ref": "#/components/schemas/ItemNumber"
                        },
                        "quantity": {
                          "type": "number"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "successful operation",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "canFulfill": {
                      "type": "boolean"
                    },
                    "fulfillmentWarehouses": {
                      "type": "array",
                      "items": {
                        "$ref": "#/components/schemas/Warehouse"
                      }
                    }
                  }
                }
              }
            }
          },
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          }
        }
      }
    },
    "/contact/{customerNumber}/{email}": {
      "put": {
        "tags": [
          "Contacts"
        ],
        "summary": "Upserts contact information",
        "description": "Upserts contact information",
        "parameters": [{
            "in": "path",
            "name": "customerNumber",
            "required": true,
            "schema": {
              "$ref": "#/components/schemas/CustomerNumber"
            }
          },
          {
            "in": "path",
            "name": "email",
            "required": true,
            "schema": {
              "type": "string",
              "format": "email"
            }
          }
        ],
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "name": {
                    "type": "string",
                    "maxLength": 30
                  }
                }
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Contact was successfully updated or created",
            "content": {
              "text/plain": {
                "schema": {
                  "type": "string"
                }
              }
            }
          },
          "400": {
            "description": "Invalid request input received",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/InvalidRequest"
                }
              }
            }
          },
          "401": {
            "description": "Unauthorized to endpoint",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/UnauthorizedRequest"
                }
              }
            }
          }
        }
      }
    }
  },
  "components": {
    "securitySchemes": {
      "api_auth": {
        "type": "apiKey",
        "in": "header",
        "name": "x-api-key"
      }
    },
    "schemas": {
      "Address": {
        "type": "object",
        "properties": {
          "contact": {
            "type": "string"
          },
          "street1": {
            "type": "string"
          },
          "street2": {
            "type": "string"
          },
          "city": {
            "type": "string"
          },
          "state": {
            "type": "string"
          },
          "zip": {
            "type": "string"
          }
        }
      },
      "ApiResponse": {
        "type": "object",
        "properties": {
          "statusCode": {
            "description": "HTTP status code. Repeated from the header.",
            "type": "integer",
            "format": "int32"
          },
          "statusMessage": {
            "description": "General status message",
            "type": "string"
          },
          "message": {
            "oneOf": [{
                "type": "string"
              },
              {
                "type": "number"
              },
              {
                "type": "object"
              },
              {
                "type": "array",
                "items": {}
              },
              {
                "type": "boolean"
              },
              {
                "type": "integer"
              }
            ]
          }
        }
      },
      "CustomerNumber": {
        "type": "string",
        "description": "Fully qualified customer number",
        "maxLength": 11,
        "pattern": "^\\d{1,8}-\\d{1,2}$"
      },
      "ItemNumber": {
        "type": "string",
        "description": "PPI Item number",
        "maxLength": 15
      },
      "LineItem": {
        "type": "object",
        "properties": {
          "lineNumber": {
            "type": "integer",
            "minimum": 1,
            "maximum": 999
          },
          "quantity": {
            "type": "integer",
            "minimum": -9999999.999,
            "maximum": 9999999.999
          },
          "itemNumber": {
            "$ref": "#/components/schemas/ItemNumber"
          },
          "unitPrice": {
            "type": "number",
            "description": "Individual net price for the item",
            "format": "currency",
            "minimum": -999999999999.999,
            "maximum": 999999999999.999
          },
          "tag": {
            "type": "string",
            "description": "Tag to add to the product"
          }
        }
      },
      "Order": {
        "type": "object",
        "properties": {
          "customerNumber": {
            "$ref": "#/components/schemas/CustomerNumber"
          },
          "indirectCustomerID": {
            "type": "integer",
            "description": "Indirect customer identifier"
          },
          "orderTime": {
            "type": "string",
            "format": "date-time"
          },
          "createdBy": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string"
              },
              "email": {
                "type": "string",
                "format": "email"
              }
            }
          },
          "currency": {
            "type": "string",
            "enum": [
              "USD",
              "CAD",
              "CLP"
            ]
          },
          "referenceOrder": {
            "type": "string"
          },
          "purchaseOrder": {
            "type": "object",
            "properties": {
              "number": {
                "type": "string"
              },
              "url": {
                "type": "string",
                "format": "url"
              },
              "documentType": {
                "type": "string",
                "enum": [
                  "PDF",
                  "XLSX",
                  "XLS"
                ]
              },
              "document": {
                "type": "string",
                "format": "binary"
              }
            }
          },
          "lineItems": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/LineItem"
            }
          },
          "shipping": {
            "type": "object",
            "properties": {
              "shipVia": {
                "type": "string"
              },
              "requestedShipDate": {
                "type": "string",
                "format": "date-time"
              },
              "carrier": {
                "type": "string"
              },
              "carrierAccountNumber": {
                "type": "string"
              },
              "delivery": {
                "type": "string",
                "enum": [
                  "Standard",
                  "No later than",
                  "Do not ship before"
                ]
              },
              "shippingAddress": {
                "$ref": "#/components/schemas/Address"
              },
              "freightBillingAddress": {
                "$ref": "#/components/schemas/Address"
              },
              "shippingInstructions": {
                "type": "string"
              }
            }
          },
          "allowSplitShipments": {
            "type": "boolean",
            "description": "If `true`, PPI may split this into multiple shipments. If this is required, or an option, and `false`, PPI may contact the `createdBy` person to determine best options on how to handle this order"
          }
        }
      },
      "OrderNumber": {
        "type": "number",
        "maximum": 999999,
        "minimum": 0,
        "description": "PPI Order number"
      },
      "Warehouse": {
        "type": "object",
        "properties": {
          "id": {
            "description": "Warehouse identifier",
            "type": "string",
            "maxLength": 1
          },
          "name": {
            "description": "Warehouse name",
            "type": "string"
          },
          "address": {
            "$ref": "#/components/schemas/Address"
          }
        }
      },
      "InvalidRequest": {
        "type": "object",
        "properties": {
          "statusCode": {
            "type": "integer",
            "description": "HTTP status code. Repeated from the header."
          },
          "error": {
            "type": "string",
            "description": "General error"
          },
          "message": {
            "type": "string",
            "description": "More detailed error"
          }
        }
      },
      "UnauthorizedRequest": {
        "type": "object",
        "properties": {
          "statusCode": {
            "type": "integer",
            "description": "HTTP status code. Repeated from the header."
          },
          "error": {
            "type": "string",
            "description": "General error"
          },
          "message": {
            "type": "string",
            "description": "More detailed error"
          }
        }
      }
    }
  }
}
